import{_ as o,o as t,c as a,a6 as r}from"./chunks/framework.BrkgobfX.js";const p=JSON.parse('{"title":"状态码：4xx 客户端错误","description":"400–451 每个码的精确触发条件，以及易混对（401/403、400/422、409/412）的判定标准。","frontmatter":{"title":"状态码：4xx 客户端错误","description":"400–451 每个码的精确触发条件，以及易混对（401/403、400/422、409/412）的判定标准。","source":"https://daiw.org/manual/http11/status-4xx"},"headers":[],"relativePath":"manual/computer-programming/http11/status-4xx.md","filePath":"manual/computer-programming/http11/status-4xx.md"}'),d={name:"manual/computer-programming/http11/status-4xx.md"};function n(i,e,c,l,s,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="状态码-4xx-客户端错误" tabindex="-1">状态码：4xx 客户端错误 <a class="header-anchor" href="#状态码-4xx-客户端错误" aria-label="Permalink to &quot;状态码：4xx 客户端错误&quot;">​</a></h1><p>4xx 表示<strong>请求有问题</strong>，除响应 <code>HEAD</code> 外 <strong>SHOULD</strong> 带解释性消息体。服务端 <strong>SHOULD</strong> 在无法确定客户端能否理解时保守选择更通用的码。</p><h2 id="_400-bad-request" tabindex="-1">400 Bad Request <a class="header-anchor" href="#_400-bad-request" aria-label="Permalink to &quot;400 Bad Request&quot;">​</a></h2><p>请求本身语法或成帧有误，服务端<strong>无法或拒绝</strong>处理。</p><p>明确要求返回 <code>400</code> 的场景（均为 MUST 级）：</p><ul><li>缺少 <code>Host</code>，或多于一个 <code>Host</code>。</li><li>字段名与冒号间有空白。</li><li>多个不一致的 <code>Content-Length</code>。</li><li>请求中 <code>Transfer-Encoding</code> 的最后一个编码不是 <code>chunked</code>。</li><li>收到 obs-fold（非 <code>message/http</code> 场景）。</li><li><code>PUT</code> 带 <code>Content-Range</code>。</li></ul><p><strong>误用警告</strong>：业务校验失败（字段值不合法但报文语法正确）<strong>不该</strong>返回 <code>400</code>——应用 <code>422</code>。<code>400</code> 属于「报文层」错误。</p><h2 id="_401-unauthorized" tabindex="-1">401 Unauthorized <a class="header-anchor" href="#_401-unauthorized" aria-label="Permalink to &quot;401 Unauthorized&quot;">​</a></h2><p><strong>未认证</strong>或认证凭据无效。</p><ul><li><strong>MUST</strong> 带 <code>WWW-Authenticate</code> 字段给出挑战，否则违反规范（客户端无从得知该怎么认证）。</li><li>客户端可携带 <code>Authorization</code> 重试。</li></ul><p>与 <code>403</code> 的判定标准：<strong><code>401</code> = 我不知道你是谁（换个身份可能行）；<code>403</code> = 我知道你是谁，但你不行（换凭据没用）</strong>。</p><h2 id="_402-payment-required" tabindex="-1">402 Payment Required <a class="header-anchor" href="#_402-payment-required" aria-label="Permalink to &quot;402 Payment Required&quot;">​</a></h2><p>保留码，无标准语义。部分 API 用于配额/欠费，非标准用法。</p><h2 id="_403-forbidden" tabindex="-1">403 Forbidden <a class="header-anchor" href="#_403-forbidden" aria-label="Permalink to &quot;403 Forbidden&quot;">​</a></h2><p>服务端理解请求但<strong>拒绝授权</strong>，且重新认证无济于事。</p><ul><li>与 <code>401</code> 的区别见上。</li><li>若不想暴露资源存在性（避免枚举），<strong>SHOULD</strong> 返回 <code>404</code> 而非 <code>403</code>。</li><li>不必带 <code>WWW-Authenticate</code>。</li></ul><h2 id="_404-not-found" tabindex="-1">404 Not Found <a class="header-anchor" href="#_404-not-found" aria-label="Permalink to &quot;404 Not Found&quot;">​</a></h2><p>无匹配的目标资源，且不透露该情况是暂时还是永久。<strong>默认可缓存</strong>——需注意误缓存。</p><h2 id="_405-method-not-allowed" tabindex="-1">405 Method Not Allowed <a class="header-anchor" href="#_405-method-not-allowed" aria-label="Permalink to &quot;405 Method Not Allowed&quot;">​</a></h2><p>方法被目标资源禁止。<strong>MUST</strong> 带 <code>Allow</code> 列出允许的方法。与 <code>501</code> 的区别见<a href="/Front2Full/manual/computer-programming/http11/methods">方法</a>。</p><h2 id="_406-not-acceptable" tabindex="-1">406 Not Acceptable <a class="header-anchor" href="#_406-not-acceptable" aria-label="Permalink to &quot;406 Not Acceptable&quot;">​</a></h2><p>按请求的<a href="/Front2Full/manual/computer-programming/http11/content-negotiation">主动协商</a>字段（<code>Accept</code> 等）找不到可接受的表示。</p><ul><li>规范允许服务端<strong>忽略协商失败直接返回其首选表示</strong>，这在实践中更常见——<code>406</code> 会让客户端彻底拿不到内容。</li><li>返回 <code>406</code> 时 <strong>SHOULD</strong> 在体中列出可用表示。</li></ul><h2 id="_407-proxy-authentication-required" tabindex="-1">407 Proxy Authentication Required <a class="header-anchor" href="#_407-proxy-authentication-required" aria-label="Permalink to &quot;407 Proxy Authentication Required&quot;">​</a></h2><p>同 <code>401</code>，但针对<strong>代理</strong>。<strong>MUST</strong> 带 <code>Proxy-Authenticate</code>；客户端用 <code>Proxy-Authorization</code> 重试。这组字段是<strong>逐跳</strong>的。</p><h2 id="_408-request-timeout" tabindex="-1">408 Request Timeout <a class="header-anchor" href="#_408-request-timeout" aria-label="Permalink to &quot;408 Request Timeout&quot;">​</a></h2><p>客户端在服务端愿意等待的时间内<strong>未发完请求</strong>。</p><ul><li><strong>SHOULD</strong> 带 <code>Connection: close</code>。</li><li>与 <code>504</code> 无关（那是网关等上游超时）。</li></ul><h2 id="_409-conflict" tabindex="-1">409 Conflict <a class="header-anchor" href="#_409-conflict" aria-label="Permalink to &quot;409 Conflict&quot;">​</a></h2><p>请求与目标资源<strong>当前状态</strong>冲突，且冲突可能由客户端自行解决。</p><ul><li>典型：版本冲突、并发编辑、<code>DELETE</code> 一个非空容器。</li><li>体 <strong>SHOULD</strong> 说明冲突原因以便客户端修正后重试。</li><li>与 <code>412</code> 的区别：<code>412</code> 是<strong>客户端显式给了前置条件且未满足</strong>；<code>409</code> 是资源自身状态不允许，无关前置条件。</li></ul><h2 id="_410-gone" tabindex="-1">410 Gone <a class="header-anchor" href="#_410-gone" aria-label="Permalink to &quot;410 Gone&quot;">​</a></h2><p>资源<strong>曾经存在、已永久移除</strong>，且无转发地址。默认可缓存。</p><p>与 <code>404</code> 的区别纯粹是「是否愿意承诺永久性」。不确定时用 <code>404</code>。</p><h2 id="_411-length-required" tabindex="-1">411 Length Required <a class="header-anchor" href="#_411-length-required" aria-label="Permalink to &quot;411 Length Required&quot;">​</a></h2><p>服务端拒绝无 <code>Content-Length</code> 的请求。客户端补上该字段后可重试。若客户端用了 <code>chunked</code> 而服务端不支持，也走这个码。</p><h2 id="_412-precondition-failed" tabindex="-1">412 Precondition Failed <a class="header-anchor" href="#_412-precondition-failed" aria-label="Permalink to &quot;412 Precondition Failed&quot;">​</a></h2><p>一个或多个<a href="/Front2Full/manual/computer-programming/http11/conditional-requests">条件请求</a>前置条件求值为<strong>假</strong>（如 <code>If-Match</code> 的 ETag 不匹配）。</p><p>用于乐观并发控制：客户端带 <code>If-Match: &quot;v1&quot;</code> 提交，资源已变为 <code>&quot;v2&quot;</code> 时返回 <code>412</code>，避免丢失更新。</p><h2 id="_413-content-too-large" tabindex="-1">413 Content Too Large <a class="header-anchor" href="#_413-content-too-large" aria-label="Permalink to &quot;413 Content Too Large&quot;">​</a></h2><p>请求体超出服务端<strong>愿意或能够</strong>处理的上限。</p><ul><li>若是暂时性限制，<strong>SHOULD</strong> 带 <code>Retry-After</code>。</li><li>曾名 <code>Payload Too Large</code>（RFC 7231）与 <code>Request Entity Too Large</code>（RFC 2616）。</li></ul><h2 id="_414-uri-too-long" tabindex="-1">414 URI Too Long <a class="header-anchor" href="#_414-uri-too-long" aria-label="Permalink to &quot;414 URI Too Long&quot;">​</a></h2><p>request-target 超长。默认可缓存。常因把大量数据塞进 query 触发——改用 <code>POST</code>。</p><h2 id="_415-unsupported-media-type" tabindex="-1">415 Unsupported Media Type <a class="header-anchor" href="#_415-unsupported-media-type" aria-label="Permalink to &quot;415 Unsupported Media Type&quot;">​</a></h2><p>请求体的<strong>格式</strong>不被目标资源支持。</p><ul><li>因 <code>Content-Type</code> 不支持 → <strong>SHOULD</strong> 带 <code>Accept</code> 列出支持的类型。</li><li>因 <code>Content-Encoding</code> 不支持 → <strong>SHOULD</strong> 带 <code>Accept-Encoding</code>。</li><li><code>PATCH</code> 的补丁格式不支持也用此码，可配 <code>Accept-Patch</code>。</li></ul><h2 id="_416-range-not-satisfiable" tabindex="-1">416 Range Not Satisfiable <a class="header-anchor" href="#_416-range-not-satisfiable" aria-label="Permalink to &quot;416 Range Not Satisfiable&quot;">​</a></h2><p><code>Range</code> 中所有范围都超出当前表示长度。</p><ul><li><strong>SHOULD</strong> 带 <code>Content-Range: bytes */&lt;完整长度&gt;</code> 告知实际长度。</li><li>注意：若<strong>部分</strong>范围可满足，服务端应返回 <code>206</code> 而非 <code>416</code>；无法满足时也可直接忽略 <code>Range</code> 返回 <code>200</code>。</li></ul><h2 id="_417-expectation-failed" tabindex="-1">417 Expectation Failed <a class="header-anchor" href="#_417-expectation-failed" aria-label="Permalink to &quot;417 Expectation Failed&quot;">​</a></h2><p><code>Expect</code> 字段中的期望无法被满足（含服务端不认识的期望值）。</p><h2 id="_418-i-m-a-teapot" tabindex="-1">418 I&#39;m a Teapot <a class="header-anchor" href="#_418-i-m-a-teapot" aria-label="Permalink to &quot;418 I&#39;m a Teapot&quot;">​</a></h2><p>RFC 2324（愚人节玩笑协议 HTCPCP）。<strong>不是 HTTP 状态码</strong>，IANA 已将 418 保留以防误用。生产勿用。</p><h2 id="_421-misdirected-request" tabindex="-1">421 Misdirected Request <a class="header-anchor" href="#_421-misdirected-request" aria-label="Permalink to &quot;421 Misdirected Request&quot;">​</a></h2><p>请求被发到<strong>无法产生响应</strong>的服务器——该服务器未被配置为该 authority 提供服务。</p><p>主要场景：HTTP/2 连接复用时，客户端复用了一条 TLS 连接向不同 authority 发请求。客户端收到后 <strong>MAY</strong> 换新连接重试。</p><h2 id="_422-unprocessable-content" tabindex="-1">422 Unprocessable Content <a class="header-anchor" href="#_422-unprocessable-content" aria-label="Permalink to &quot;422 Unprocessable Content&quot;">​</a></h2><p>语法正确、<code>Content-Type</code> 支持，但<strong>语义上无法处理</strong>（业务校验失败）。</p><p>这是 API 返回参数校验错误的正确码，不是 <code>400</code>。RFC 4918 引入，RFC 9110 已纳入核心。</p><h2 id="_423-424-425-426" tabindex="-1">423 / 424 / 425 / 426 <a class="header-anchor" href="#_423-424-425-426" aria-label="Permalink to &quot;423 / 424 / 425 / 426&quot;">​</a></h2><table tabindex="0"><thead><tr><th>码</th><th>名称</th><th>语义</th></tr></thead><tbody><tr><td><code>423</code></td><td>Locked</td><td>WebDAV，资源被锁定</td></tr><tr><td><code>424</code></td><td>Failed Dependency</td><td>WebDAV，依赖的前序操作失败</td></tr><tr><td><code>425</code></td><td>Too Early</td><td>RFC 8470，拒绝处理 TLS 早期数据（0-RTT）中的请求，防重放</td></tr><tr><td><code>426</code></td><td>Upgrade Required</td><td>必须升级协议。<strong>MUST</strong> 带 <code>Upgrade</code> 字段</td></tr></tbody></table><h2 id="_428-precondition-required" tabindex="-1">428 Precondition Required <a class="header-anchor" href="#_428-precondition-required" aria-label="Permalink to &quot;428 Precondition Required&quot;">​</a></h2><p>RFC 6585。服务端要求请求<strong>必须</strong>带前置条件——强制客户端使用 <code>If-Match</code> 以避免丢失更新。</p><h2 id="_429-too-many-requests" tabindex="-1">429 Too Many Requests <a class="header-anchor" href="#_429-too-many-requests" aria-label="Permalink to &quot;429 Too Many Requests&quot;">​</a></h2><p>RFC 6585。超出速率限制。<strong>SHOULD</strong> 带 <code>Retry-After</code>。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Retry-After = HTTP-date / delay-seconds</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>两种形式：<code>Retry-After: 120</code>（秒）或 <code>Retry-After: Wed, 21 Oct 2026 07:28:00 GMT</code>。</p><h2 id="_431-request-header-fields-too-large" tabindex="-1">431 Request Header Fields Too Large <a class="header-anchor" href="#_431-request-header-fields-too-large" aria-label="Permalink to &quot;431 Request Header Fields Too Large&quot;">​</a></h2><p>RFC 6585。字段区总量或单个字段过大。可只针对单个超限字段返回，体中应指明是哪个。</p><h2 id="_451-unavailable-for-legal-reasons" tabindex="-1">451 Unavailable For Legal Reasons <a class="header-anchor" href="#_451-unavailable-for-legal-reasons" aria-label="Permalink to &quot;451 Unavailable For Legal Reasons&quot;">​</a></h2><p>RFC 7725。因法律要求不可用。<strong>SHOULD</strong> 带 <code>Link</code> 字段（<code>rel=&quot;blocked-by&quot;</code>）指向实施封锁的实体。与 <code>403</code> 的区别是明确归因于法律而非授权。</p><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/status-5xx">状态码：5xx 服务端错误</a>。</p>',73)])])}const g=o(d,[["render",n]]);export{p as __pageData,g as default};
